    public virtual void handleOrder(WebSocketClient client, Dictionary<string, object> message)
    {
        //
        //     {
        //         "T": 1766588450558,
        //         "E": 1766588450685,
        //         "e": "ORDER_TRADE_UPDATE",
        //         "o": {
        //             "S": "BUY",
        //             "ap": "0",
        //             "cpt": false,
        //             "ct": "future",
        //             "ev": "0",
        //             "fee": "0",
        //             "lv": 2,
        //             "mt": "isolated",
        //             "o": "7409609004526010368",
        //             "p": "1000",
        //             "ps": "BOTH",
        //             "pt": "ONE_WAY",
        //             "ro": false,
        //             "s": "ETH-USDC",
        //             "st": "NEW",
        //             "t": "LIMIT",
        //             "tp": "0",
        //             "u": "0.001",
        //             "v": "2"
        //         }
        //     }
        //
        IDictionary<string, object> rawOrder = this.safeDict(message, "o", new Dictionary<string, object>() {});
        string? marketId = this.safeString(rawOrder, "s");
        Dictionary<string, object> market = this.safeMarket(marketId);
        string? symbol = ((string)(market.ContainsKey("symbol") ? market["symbol"] : null));
        string messageHash = "orders";
        string symbolMessageHash = ((messageHash + "::") + symbol);
        if ((this.orders == null))
        {
            Int64? limit = this.safeInteger(this.options, "ordersLimit", 1000);
            this.orders = new ArrayCacheBySymbolById(limit);
        }
        ccxt.pro.ArrayCache orders = this.orders;
        Dictionary<string, object> order = this.parseWsOrder(rawOrder, market);
        Int64? lastUpdateTimestamp = this.safeInteger(message, "T");
        order["lastUpdateTimestamp"] = lastUpdateTimestamp;
        orders.append(order);
        client.resolve(orders, messageHash);
        client.resolve(orders, symbolMessageHash);
    }

    public override Dictionary<string, object> parseWsOrder(object order, IDictionary<string, object> market = null)
    {
        //
        //     {
        //         "S": "BUY",
        //         "ap": "0",
        //         "cpt": false,
        //         "ct": "future",
        //         "ev": "0",
        //         "fee": "0",
        //         "lv": 2,
        //         "mt": "isolated",
        //         "o": "7409609004526010368",
        //         "p": "1000",
        //         "ps": "BOTH",
        //         "pt": "ONE_WAY",
        //         "ro": false,
        //         "s": "ETH-USDC",
        //         "st": "NEW",
        //         "t": "LIMIT",
        //         "tp": "0",
        //         "u": "0.001",
        //         "v": "2"
        //     }
        //
        string? marketId = this.safeString(order, "s");
        Dictionary<string, object> marketResolved = this.safeMarket(marketId, market);
        string? rawStatus = this.safeString(order, "st");
        string? rawType = this.safeString(order, "t");
        Dictionary<string, object> fee = null;
        string? feeCost = this.safeString(order, "fee");
        if ((feeCost != null))
        {
            fee = new Dictionary<string, object>() {
                { "cost", Precise.stringAbs(feeCost) },
                { "currency", (marketResolved != null && ((IDictionary<string, object>)marketResolved).ContainsKey("quote") ? ((IDictionary<string, object>)marketResolved)["quote"] : null) },
            };
        }
        return this.safeOrder(new Dictionary<string, object>() {
            { "info", order },
            { "id", this.safeString(order, "o") },
            { "clientOrderId", this.safeString(order, "cid") },
            { "timestamp", null },
            { "datetime", null },
            { "lastTradeTimestamp", null },
            { "lastUpdateTimestamp", null },
            { "status", this.parseOrderStatus(rawStatus) },
            { "symbol", (marketResolved != null && ((IDictionary<string, object>)marketResolved).ContainsKey("symbol") ? ((IDictionary<string, object>)marketResolved)["symbol"] : null) },
            { "type", this.parseOrderType(rawType) },
            { "timeInForce", null },
            { "postOnly", null },
            { "reduceOnly", this.safeBool(order, "ro") },
            { "side", this.safeStringLower(order, "S") },
            { "price", this.safeString(order, "p") },
            { "triggerPrice", null },
            { "stopLossPrice", null },
            { "takeProfitPrice", null },
            { "amount", this.safeString(order, "v") },
            { "filled", this.safeString(order, "ev") },
            { "remaining", this.safeString(order, "qty") },
            { "cost", null },
            { "trades", null },
            { "fee", fee },
            { "average", this.omitZero(this.safeString(order, "ap")) },
        }, marketResolved);
    }

